class Cache:
    def __init__(self):
        self.entries = {}

    def put(self, key, value, ttl, now):
        if ttl < 0:
            raise ValueError('negative ttl')
        self.entries[key] = (value, now + ttl)

    def get(self, key, now):
        item = self.entries.get(key)
        if item is None:
            return None
        value, expiry = item
        if now > expiry:
            del self.entries[key]
            return None
        return value

